const updateRecipe = `-- name: UpdateRecipe :execrows
UPDATE recipes SET name = ?, description = ?, work_minutes = ?, wait_minutes = ?, servings = ?, servings_text = ?,
  source_url = ?, visibility = ?, search_text = ?, version = version + 1,
  updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now')
WHERE id = ?10 AND version = ?11 AND deleted_at IS NULL
`

type UpdateRecipeParams struct {
	Name         string
	Description  string
	WorkMinutes  int64
	WaitMinutes  int64
	Servings     int64
	ServingsText string
	SourceUrl    string
	Visibility   string
	SearchText   string
	ID           int64
	BaseVersion  int64
}

func (q *Queries) UpdateRecipe(ctx context.Context, arg UpdateRecipeParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateRecipe,
		arg.Name,
		arg.Description,
		arg.WorkMinutes,
		arg.WaitMinutes,
		arg.Servings,
		arg.ServingsText,
		arg.SourceUrl,
		arg.Visibility,
		arg.SearchText,
		arg.ID,
		arg.BaseVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
